from unittest.mock import patch
from myapp import fetch_user_count

@patch("myapp.requests.get")
def test_fetch_user_count(mock_get):
    mock_get.return_value.json.return_value = {"count": 42}
    assert fetch_user_count() == 42
    mock_get.assert_called_once()

from unittest.mock import patch
import mymodule

@patch("mymodule.datetime")
def test_partition_path(mock_dt):
    mock_dt.utcnow.return_value.strftime.return_value = "2024-01-15"
    assert mymodule.partition_path() == "data/2024-01-15/"
